/* Dashboard sem build: a amostra abaixo permite abrir o index.html diretamente. */
const produtos = [
  ['X-Bacon','Lanche',29.9], ['X-Salada','Lanche',27.9], ['X-Frango','Lanche',26.9],
  ['Batata P','Acompanhamento',12.9], ['Batata G','Acompanhamento',18.9],
  ['Milkshake','Sobremesa',16.9], ['Brownie','Sobremesa',14.9], ['Refrigerante','Bebida',7.9]
];
const regioes = ['Centro','Zona Norte','Zona Sul','Zona Leste','Zona Oeste'];
const pad = n => String(n).padStart(2,'0');
function gerarAmostra() {
  return Array.from({length: 200}, (_, i) => {
    const mes = (i % 12) + 1, dia = ((i * 7) % 27) + 1, p = produtos[i % produtos.length];
    // A amostra começa com números reais, evitando concatenação de textos na soma.
    return { id_venda: String(i + 1), data: `2025-${pad(mes)}-${pad(dia)}`, produto: p[0], categoria: p[1], regiao: regioes[(i * 3) % regioes.length], quantidade: (i % 4) + 1, preco_unitario: p[2] };
  });
}

