function summarize(rows) { const ids=new Set(rows.map(r=>r.id_venda)); const revenue=rows.reduce((sum,r)=>sum+Number(r.quantidade)*Number(r.preco_unitario),0); return {revenue, sales:ids.size, units:rows.reduce((sum,r)=>sum+Number(r.quantidade),0), ticket:ids.size ? revenue/ids.size : 0}; }
