function monthStats(rows) { const map={}; rows.forEach(r=>{const key=r.data.slice(0,7); if(!map[key])map[key]={revenue:0,units:0,sales:new Set()}; map[key].revenue+=Number(r.quantidade)*Number(r.preco_unitario); map[key].units+=Number(r.quantidade); map[key].sales.add(r.id_venda);}); return Object.entries(map).sort(([a],[b])=>a.localeCompare(b)).map(([month,v])=>({...v,month,sales:v.sales.size})); }
