  summaryEl.textContent=`${number(summary.sales)} vendas geraram ${money(summary.revenue)}. ${topCategory[0]} lidera o faturamento com ${money(topCategory[1])}.${state.invalidCount ? ` Foram descartados ${number(state.invalidCount)} registros inválidos.` : ''}`;
