function aggregate(rows,key) { return rows.reduce((out,r) => { const label=r[key]; out[label]=(out[label]||0)+r.quantidade*r.preco_unitario; return out; },{}); }
function aggregateUnits(rows,key) { return rows.reduce((out,r) => { const label=r[key]; out[label]=(out[label]||0)+Number(r.quantidade); return out; },{}); }
function aggregateSalesByWeekday(rows) { const names=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'], out=Object.fromEntries(names.map(name=>[name,0])); rows.forEach(r=>{const day=new Date(`${r.data}T12:00:00`).getDay(); out[names[day]]+=1;}); return out; }
function updateCharts(rows) {
  const months=monthStats(rows), labels=months.map(v=>formatMonth(v.month));
  draw('monthlyChart','line',labels,months.map(v=>v.revenue),'#00e5ff'); const cat=aggregate(rows,'categoria'); draw('categoryChart','bar',Object.keys(cat),Object.values(cat),'#ff0099'); const reg=aggregate(rows,'regiao'); draw('regionChart','bar',Object.keys(reg),Object.values(reg),'#b6ff00');
  const catUnits=aggregateUnits(rows,'categoria'); draw('unitsCategoryChart','bar',Object.keys(catUnits),Object.values(catUnits),'#9b6cff','Unidades');
  const products=Object.entries(aggregate(rows,'produto')).sort((a,b)=>b[1]-a[1]).slice(0,8); draw('productChart','bar',products.map(v=>v[0]),products.map(v=>v[1]),'#00e5ff','Faturamento');
  const weekday=aggregateSalesByWeekday(rows); draw('weekdayChart','bar',Object.keys(weekday),Object.values(weekday),'#ff3cac','Vendas');
}
function draw(id,type,labels,data,color,metric='Faturamento'){ if(state.charts[id])state.charts[id].destroy(); const monetary=metric==='Faturamento'; state.charts[id]=new Chart($(id),{type,data:{labels,datasets:[{label:metric,data,backgroundColor:type==='line'?color+'22':color,borderColor:color,borderWidth:2,fill:type==='line',tension:.35,borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>` ${monetary?money(c.raw):number(c.raw)} ${monetary?'':'registros'}`}}},scales:{x:{grid:{display:false},ticks:{color:'#8ba4b8'}},y:{beginAtZero:true,grid:{color:'#24364a'},ticks:{color:'#8ba4b8',callback:v=>monetary?money(v):number(v)}}}}}); }
function updateTable(rows) { const sorted=[...rows].sort((a,b)=>String(a[state.sortKey]).localeCompare(String(b[state.sortKey]),'pt-BR',{numeric:true})*(state.sortDir==='asc'?1:-1)); $('tableBody').innerHTML=sorted.map(r=>`<tr><td>${escapeHtml(r.id_venda)}</td><td>${new Intl.DateTimeFormat('pt-BR').format(new Date(`${r.data}T12:00:00`))}</td><td>${escapeHtml(r.produto)}</td><td>${escapeHtml(r.categoria)}</td><td>${escapeHtml(r.regiao)}</td><td class="number">${number(r.quantidade)}</td><td class="number">${money(r.preco_unitario)}</td><td class="number">${money(r.quantidade*r.preco_unitario)}</td></tr>`).join(''); $('salesTable').hidden=rows.length===0; $('emptyState').hidden=rows.length!==0; }
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function render(){const rows=filteredRows();updateMetrics(rows);updateInsights(rows);updateCharts(rows);updateTable(rows);}
function loadRows(raw, source) { const valid=raw.map(normalize).filter(Boolean); if(!valid.length){alert('Não foi possível encontrar registros válidos. Confira as colunas id_venda, data, quantidade e preco_unitario.');return;} state.rows=valid;state.source=source;state.invalidCount=Math.max(0,raw.length-valid.length);state.search='';$('searchInput').value='';$('sourceBadge').innerHTML=`<span class="status-dot"></span> ${source==='demo'?'Dados demonstrativos':'CSV importado'}`;$('dataMessage').textContent=source==='demo'?'A amostra está incorporada na página para funcionar mesmo ao abrir o arquivo diretamente. Selecione um CSV para substituí-la.':`${valid.length} registros válidos importados localmente. Registros com data ou números inválidos foram ignorados.`;populateFilters();$('startDate').value='';$('endDate').value='';$('categoryFilter').value='';$('regionFilter').value='';render();}
$('csvInput').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;Papa.parse(file,{header:true,skipEmptyLines:true,complete:result=>loadRows(result.data,'file')});});
['startDate','endDate','categoryFilter','regionFilter'].forEach(id=>$(id).addEventListener('change',render));
$('searchInput').addEventListener('input',e=>{state.search=e.target.value.toLocaleLowerCase('pt-BR').trim();render();});
$('clearFilters').addEventListener('click',()=>{$('startDate').value='';$('endDate').value='';$('categoryFilter').value='';$('regionFilter').value='';state.search='';$('searchInput').value='';render();});
document.querySelectorAll('th[data-key]').forEach(th=>th.addEventListener('click',()=>{const key=th.dataset.key;state.sortDir=state.sortKey===key&&state.sortDir==='asc'?'desc':'asc';state.sortKey=key;render();}));
$('exportCsv').addEventListener('click',()=>{const rows=filteredRows();if(!rows.length)return;const csv=Papa.unparse(rows.map(r=>({...r,faturamento:(r.quantidade*r.preco_unitario).toFixed(2)})));const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='vendas-filtradas.csv';a.click();URL.revokeObjectURL(a.href);});
populateFilters();render();



